const WORLDS_KEY='ryadom-worlds-v1';
const worldSave=()=>{try{return JSON.parse(localStorage.getItem(WORLDS_KEY)||'{}')}catch{return {}}};let activeWorld=-1,worldState=null;
function saveWorld(){let all=worldSave();all[activeWorld]=worldState;localStorage.setItem(WORLDS_KEY,JSON.stringify(all))}
function worldFrame(){document.querySelector('#gamesHub').hidden=true;let root=document.querySelector('#gamePlay');root.hidden=false;root.replaceChildren();let bar=document.createElement('div');bar.className='story-top';let back=document.createElement('button');back.textContent='← К играм';back.onclick=showHub;let label=document.createElement('span');label.textContent=worldSpecs[activeWorld].title.toUpperCase();bar.append(back,label);root.append(bar);return root}
function worldMeter(label,value){let row=document.createElement('div');row.className='relation';row.innerHTML='<label><span></span><span></span></label><div class="relation-meter"><i></i></div>';row.querySelector('label span:first-child').textContent=label;row.querySelector('label span:last-child').textContent=value+'%';row.querySelector('i').style.width=value+'%';return row}
function renderWorld(){let spec=worldSpecs[activeWorld],s=worldState,root=worldFrame();if(s.chapter>=4){let box=document.createElement('div');box.className='story-ending world-ending';let cap=document.createElement('span');cap.className='eyebrow';cap.textContent='История пройдена';let h=document.createElement('h2');h.textContent=spec.title;let p=document.createElement('p');p.textContent=s.agency>=55?'За четыре главы удалось сделать несколько собственных выборов. Отношения героев менялись вместе с ними. Эту историю можно пройти по-другому.':'Герой пока ищет свой темп. Один путь не определяет человека и его отношения. Можно вернуться и попробовать другой выбор.';let btn=document.createElement('button');btn.className='primary';btn.textContent='Сыграть иначе';btn.onclick=()=>startWorld(activeWorld,true);let home=document.createElement('button');home.className='secondary';home.textContent='К играм';home.onclick=showHub;box.append(cap,h,p,btn,home);root.append(box);return}
let scene=spec.scenes[s.chapter],heading=document.createElement('div');heading.className='story-title';let title=document.createElement('h2');title.textContent=scene[0];let count=document.createElement('span');count.textContent='Глава '+(s.chapter+1)+' / 4';heading.append(title,count);root.append(heading);let pips=document.createElement('div');pips.className='chapter-pips';for(let i=0;i<4;i++){let pip=document.createElement('i');if(i<=s.chapter)pip.className='done';pips.append(pip)}root.append(pips);
let shell=document.createElement('div');shell.className='story-shell';let main=document.createElement('div');main.className='story-main';let art=document.createElement('div');art.className='world world-alt world-theme-'+spec.theme;let label=document.createElement('span');label.className='scene-label';label.textContent=spec.title+' · '+scene[0];let symbol=document.createElement('span');symbol.className='world-symbol';symbol.textContent=['✉','⌂','☼','◇'][s.chapter];let figures=document.createElement('div');figures.className='world-figures';let first=document.createElement('div');first.innerHTML='<span></span><b></b>';first.querySelector('b').textContent=spec.hero;let second=document.createElement('div');second.innerHTML='<span></span><b></b>';second.querySelector('b').textContent=spec.other;figures.append(first,second);let object=document.createElement('button');object.className='world-object';object.textContent='✦ '+scene[3];object.onclick=()=>{s.seen=true;saveWorld();renderWorld();document.querySelector('#worldDetail').textContent=scene[4]};art.append(label,symbol,figures,object);main.append(art);
let card=document.createElement('div');card.className='card scene-card';say(card,'Рассказчик',scene[1]);say(card,spec.other,scene[2].replace(spec.other+': ','').replace(spec.other+':',''));let info=document.createElement('div');info.id='worldDetail';info.className='scene-info';info.textContent=s.seen?scene[4]:'Осмотри предмет в сцене, чтобы открыть выбор.';card.append(info);let prompt=document.createElement('div');prompt.className='scene-prompt';prompt.textContent='Что делает '+spec.hero+'?';card.append(prompt);let actions=document.createElement('div');actions.className='scene-actions';for(let i=0;i<3;i++){let option=scene[5+i],b=document.createElement('button');b.textContent=option[0];b.disabled=!s.seen||s.choice!==null;b.onclick=()=>{s.choice=i;s.relation=Math.max(5,Math.min(95,s.relation+option[2]));s.agency=Math.max(5,Math.min(95,s.agency+option[3]));saveWorld();renderWorld()};actions.append(b)}if(s.choice!==null){actions.hidden=true;let chosen=scene[5+s.choice];say(card,spec.hero,chosen[0],true);say(card,spec.other,chosen[1]);let next=document.createElement('button');next.className='primary scene-advance';next.textContent=s.chapter===3?'Увидеть финал →':'Следующая глава →';next.onclick=()=>{s.chapter++;s.seen=false;s.choice=null;saveWorld();renderWorld()};card.append(next)}card.append(actions);main.append(card);let side=document.createElement('div');side.className='story-side';let stats=document.createElement('div');stats.className='card';let sh=document.createElement('h3');sh.textContent='Отношения в истории';stats.append(sh,worldMeter(spec.relation,s.relation),worldMeter(spec.agency,s.agency));let hint=document.createElement('p');hint.className='hint';hint.textContent='Эти числа отражают только сюжетные выборы. Они не оценивают тебя или реальные отношения.';stats.append(hint);side.append(stats);shell.append(main,side);root.append(shell)}
function startWorld(i,restart=false){activeWorld=i;let all=worldSave();worldState=restart?null:all[i];if(!worldState){worldState={chapter:0,seen:false,choice:null,relation:50,agency:35};saveWorld()}renderWorld()}
[...document.querySelector('#gameGrid').children].forEach((card,i)=>{card.setAttribute('role','button');card.tabIndex=0;card.setAttribute('aria-label','Играть: '+worldSpecs[i].title);card.querySelector('small').textContent='ИГРАТЬ · 4 ГЛАВЫ';card.onclick=()=>startWorld(i);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();startWorld(i)}}});
document.querySelector('.game-note').textContent='Все тринадцать историй доступны. Решения меняют отношения героев и финал; игровой прогресс хранится отдельно от дневника.';
